source.css:
body { margin: 0; }
.stage { position: absolute; inset: 0; font-family: inter, sans-serif; }
.a { animation: rise; }
.b { animation: spin 1s linear infinite; }
.c { animation: rise 0.6s ease-out 2s; }
.d { animation: rise 1s ease-out 5.5s both; }
.e { animation: missing 1s ease 0s both; }
@keyframes rise { from { opacity: 0 } to { opacity: 1 } }
@keyframes spin { to { transform: rotate(360deg) } }
@keyframes unused { to { opacity: 0 } }
